//! Everything a node runs, in one place (`NodeServices` of `node/app.ts`
//! and the locals of `startNode`). Owner: **core**, which builds it in
//! [`Services::start`]; the field list is the layout's interface. Other
//! workers do not edit this file: a component that needs more state keeps
//! it in its own type, and reaches other components through the [`Node`]
//! it is given.
//!
//! Components are built in one step with [`std::sync::Arc::new_cyclic`]:
//! a component that needs others at run time takes a [`WeakNode`] in its
//! constructor and upgrades it when it works (the node outlives every
//! task: `main` holds it until [`Services::close`] returns). Route handlers
//! and link hooks get the [`Node`] itself.

use pirc_protocol::{Mode, ModeId};
use std::collections::BTreeMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, RwLock, Weak};

use pirc_config::{Env, NodeConfig};
use tokio::sync::{Notify, watch};

use crate::agent_gateway::AgentGateway;
use crate::branch_cache::BranchCache;
use crate::browser::BrowserService;
use crate::events::EventHub;
use crate::inference::InferenceServer;
use crate::link::LinkSender;
use crate::memory_mirror::MemoryMirror;
use crate::models::ModelStore;
use crate::router::Router;
use crate::runner::RunnerManager;
use crate::sandbox::Sandbox;
use crate::store::{Db, Store};
use crate::streams::Streams;
use crate::terminals::Terminals;
use crate::write_broker::WriteBroker;

/// The running node.
pub type Node = Arc<Services>;
/// What components hold: see the module documentation.
pub type WeakNode = Weak<Services>;

pub struct Services {
    pub config: NodeConfig,
    /// The node's own environment, read once at start: the base of every
    /// child's environment (`pirc_config::env_allowlist::without_secrets`).
    pub env: Env,
    /// The node's SQLite store (core).
    pub db: Db,
    pub events: Arc<EventHub>,
    /// The gateway's catalog with the node's inference socket.
    pub models: ModelStore,
    pub modes: RwLock<BTreeMap<ModeId, Mode>>,
    /// Frames to the gateway (layout; the client is core's).
    pub link: LinkSender,
    /// Open runs or write leases changed: the link sends `activity` (TS
    /// `db.onRunsChanged` and `writes.onChange`). Whoever creates or updates
    /// a run, or changes leases, calls `node.activity.notify_one()`.
    pub activity: Notify,
    /// The request router (`app::routes()` and `panels::routes()`).
    pub router: Router,
    // runner
    pub writes: WriteBroker,
    pub checkpoints: Option<Arc<crate::checkpoints::runtime::CaptureService>>,
    pub(crate) recovery_roots: RwLock<BTreeMap<String, String>>,
    pub branches: BranchCache,
    pub agent_gateway: AgentGateway,
    pub inference: InferenceServer,
    pub runners: RunnerManager,
    pub(crate) pots: crate::pots::Pots,
    pub(crate) execution_drains: Arc<crate::execution_fences::Drains>,
    // panels
    pub terminals: Terminals,
    pub streams: Streams,
    pub mirror: MemoryMirror,
    // sandbox
    pub sandbox: Arc<dyn Sandbox>,
    // manager: the agent browser (`browser::manager::BrowserManager`).
    pub browser: Arc<dyn BrowserService>,
    // core: the link's stop (TS `stopped` and `socket.terminate()`).
    closing: AtomicBool,
    terminate: watch::Sender<bool>,
}

/// The node is shared by every task of the multi-threaded runtime.
const _: fn() = || {
    fn shared<T: Send + Sync>() {}
    shared::<Services>();
};

impl Services {
    pub fn mode(&self, id: &ModeId) -> crate::error::ApiResult<Mode> {
        if !self.config.modes.contains(id) {
            return Err(crate::error::ApiError::forbidden(
                "Node does not accept this mode",
            ));
        }
        self.modes
            .read()
            .unwrap_or_else(|e| e.into_inner())
            .get(id)
            .cloned()
            .ok_or_else(|| {
                crate::error::ApiError::new(
                    409,
                    "mode_unavailable",
                    format!("Mode {id} is unavailable"),
                )
            })
    }

    pub fn workspace_mode(
        &self,
        workspace: &crate::store::Workspace,
    ) -> crate::error::ApiResult<Mode> {
        let mut mode = self.mode(&workspace.mode)?;
        if self
            .recovery_roots
            .read()
            .unwrap_or_else(|e| e.into_inner())
            .contains_key(&workspace.id)
        {
            mode.workspace_memory = false;
        }
        let state = self.config.state_dir.canonicalize().map_err(|_| {
            crate::error::ApiError::new(
                409,
                "mode_unavailable",
                "Node state directory is unavailable",
            )
        })?;
        let expected = state.join("chat").join(&workspace.id);
        let actual = std::path::Path::new(&workspace.canonical_path);
        let expected = expected.canonicalize().unwrap_or(expected);
        let managed = actual == expected;
        let compatible = match mode.workdir {
            pirc_protocol::mode::Workdir::PerSession => managed,
            pirc_protocol::mode::Workdir::Workspace => {
                !actual.starts_with(&state)
                    || self
                        .recovery_roots
                        .read()
                        .unwrap_or_else(|e| e.into_inner())
                        .get(&workspace.id)
                        == Some(&workspace.canonical_path)
            }
        };
        if !compatible {
            return Err(crate::error::ApiError::new(
                409,
                "mode_unavailable",
                "Mode workdir is incompatible with stored workspace layout",
            ));
        }
        Ok(mode)
    }

    pub fn session_mode(&self, session_id: &str) -> crate::error::ApiResult<Mode> {
        crate::execution_fences::require_open(&self.db.lock(), session_id)?;
        self.session_mode_for_control(session_id)
    }

    /// Keep existing mode checks for control operations without treating a
    /// transition's execution fence as a prohibition on taking control to Stop.
    pub(crate) fn session_mode_for_control(
        &self,
        session_id: &str,
    ) -> crate::error::ApiResult<Mode> {
        let db = self.db.lock();
        let session = db.get_session(session_id)?;
        let workspace = db.get_workspace(&session.workspace_id)?;
        let mode = self.workspace_mode(&workspace)?;
        drop(db);
        if self
            .runners
            .get(session_id)
            .is_some_and(|runner| runner.mode_snapshot() != &mode)
        {
            return Err(crate::error::ApiError::new(
                409,
                "mode_unavailable",
                "Mode changed; runner is stopping",
            ));
        }
        Ok(mode)
    }

    pub async fn replace_modes(&self, modes: Vec<Mode>) {
        let next: BTreeMap<_, _> = modes
            .into_iter()
            .map(|mode| (mode.id.clone(), mode))
            .collect();
        let old = std::mem::replace(
            &mut *self.modes.write().unwrap_or_else(|e| e.into_inner()),
            next.clone(),
        );
        if old != next {
            self.inference.disconnect();
        }
        let sessions = {
            let db = self.db.lock();
            db.list_workspaces()
                .unwrap_or_default()
                .into_iter()
                .filter(|workspace| old.get(&workspace.mode) != next.get(&workspace.mode))
                .flat_map(|workspace| db.workspace_sessions(&workspace.id).unwrap_or_default())
                .map(|session| session.id)
                .collect::<Vec<_>>()
        };
        for id in sessions {
            let _ = self.runners.stop_session(&id).await;
            self.terminals.dispose_session(&id).await;
        }
    }

    /// `buildNodeApp` and the start of `startNode` (owner: **core**):
    ///
    /// 1. Refuse a TS-era `gateway.sqlite` and open the store
    ///    ([`Db::open`]); refuse state whose workspaces belong to the other
    ///    role ("State contains workspaces incompatible with ..."), without
    ///    changing them.
    /// 2. `sync_workspaces`, the chat node's top-level chats
    ///    (`chat::ensure_top_level_chats`), `recover_startup` (logged).
    /// 3. Build the components (`Arc::new_cyclic`), start the sandbox probe
    ///    in the background (log "agent sandbox ready" or "agent sandbox
    ///    unavailable, no agent can start: <reason>"), warn about legacy
    ///    `config.json` model and role keys, start the inference socket
    ///    and put its config into `models` before the link connects.
    pub async fn start(config: NodeConfig, env: Env) -> Result<Node, String> {
        crate::link::endpoint(&config.daemon_url)?;
        pirc_config::registry::register_node(&config, &env, None)
            .map_err(|error| format!("cannot register node private directories: {error}"))?;
        let legacy = config.state_dir.join("gateway.sqlite");
        if legacy != config.database_path {
            crate::store::refuse_typescript_database(&legacy)?;
        }
        let db = Db::open(&config.database_path)?;
        {
            let connection = db.lock();
            // A store failure exits with its SQLite text, as TS did.
            let failed = |error: crate::error::ApiError| error.startup_text();
            // The role is fixed across restarts: never expose the other
            // role's persisted workspaces.
            crate::store::check_role(
                &connection.list_workspaces().map_err(failed)?,
                &config.modes,
            )?;
            connection
                .sync_workspaces(&config.node_id, &config.workspaces)
                .map_err(failed)?;
            if config.chat() && config.modes.iter().any(|mode| mode.as_str() == "chat") {
                crate::chat::ensure_top_level_chats(&config, &connection).map_err(failed)?;
            }
            let recovery = connection.recover_startup().map_err(failed)?;
            crate::log::info(&format!(
                "node startup recovery complete: {}",
                serde_json::json!({ "recovery": recovery })
            ));
        }
        let sandbox = crate::sandbox::create(&config, &env);
        // Launches nothing until an agent or a viewer opens a page.
        let browser: Arc<dyn BrowserService> =
            Arc::new(crate::browser::manager::BrowserManager::new(&config, &env));
        let events = EventHub::new(config.event_buffer_size);
        let router = Router::new(
            crate::app::routes(&config)
                .into_iter()
                .chain(crate::panels::routes())
                .chain(crate::checkpoints::api::routes()),
        );
        let (terminate, _) = watch::channel(false);
        let checkpoints = crate::checkpoints::runtime::CaptureService::configured(&config, &env)?;
        if let Some(service) = &checkpoints {
            service
                .load_inherited(&db.lock())
                .map_err(|e| e.startup_text())?;
        }
        let recovery_roots =
            crate::checkpoints::continuation::roots(&db.lock()).map_err(|e| e.startup_text())?;
        let node = Arc::new_cyclic(|weak: &WeakNode| Services {
            config,
            env,
            db,
            events,
            models: ModelStore::new(),
            modes: RwLock::new(BTreeMap::new()),
            link: LinkSender::new(),
            activity: Notify::new(),
            router,
            writes: WriteBroker::new(weak.clone()),
            checkpoints,
            recovery_roots: RwLock::new(recovery_roots),
            branches: BranchCache::new(),
            agent_gateway: AgentGateway::new(weak.clone()),
            inference: InferenceServer::new(weak.clone()),
            runners: RunnerManager::new(weak.clone()),
            pots: crate::pots::Pots::default(),
            execution_drains: Arc::default(),
            terminals: Terminals::new(weak.clone()),
            streams: Streams::new(weak.clone()),
            mirror: MemoryMirror::new(weak.clone()),
            sandbox,
            browser,
            closing: AtomicBool::new(false),
            terminate,
        });
        if let Some(capture) = &node.checkpoints {
            tokio::spawn(capture.clone().maintenance(node.terminate.subscribe()));
        }
        // Mandatory: say at start-up whether agents can start at all.
        let probe = node.sandbox.clone();
        tokio::spawn(async move {
            match probe.check().await {
                crate::sandbox::SandboxStatus::Active { description } => {
                    crate::log::info(&format!("agent sandbox ready: {description}"));
                }
                crate::sandbox::SandboxStatus::Unavailable { reason } => {
                    crate::log::error(&format!(
                        "agent sandbox unavailable, no agent can start: {reason}"
                    ));
                }
            }
        });
        warn_legacy_config(&node.config);
        let inference = node.inference.start().await?;
        // Even before registration, never fall back to direct provider inference.
        node.models.set_inference(Some(inference));
        Ok(node)
    }

    /// Whether the node is closing: the link does not reconnect.
    pub fn closing(&self) -> bool {
        self.closing.load(Ordering::Acquire)
    }

    /// Resolves when the link must go (`socket.terminate()`).
    pub fn terminated(&self) -> watch::Receiver<bool> {
        self.terminate.subscribe()
    }

    /// `close` of `startNode` and Fastify's `onClose` (owner: **core**):
    /// stop the link (no reconnect, `terminate` without a close frame),
    /// close streams and terminals, disconnect the agent gateway and the
    /// mirror, close the inference socket, stop every runner (grace
    /// `config.shutdown_grace_ms`), shut the browser down.
    pub async fn close(&self) {
        // TS's order: no reconnect from now on, then the streams, the agent
        // gateway, the mirror and inference, then the socket.
        self.closing.store(true, Ordering::Release);
        self.streams.close_all();
        self.agent_gateway.disconnect();
        self.mirror.disconnect();
        self.inference.close().await;
        self.terminate.send_replace(true);
        // Fastify's `onClose`.
        self.terminals.shutdown();
        self.runners.shutdown().await;
        self.browser.shutdown().await;
    }
}

/// `legacyModelKeys` and `legacyRoleConfig`: settings the gateway or role
/// files took over, left in `config.json` (an unreadable file is reported
/// when an agent starts, not here).
fn warn_legacy_config(config: &NodeConfig) {
    let Ok(text) = std::fs::read_to_string(config.config_dir.join("config.json")) else {
        return;
    };
    let Ok(serde_json::Value::Object(raw)) = serde_json::from_str::<serde_json::Value>(&text)
    else {
        return;
    };
    let keys: Vec<&str> = ["providers", "defaultModel"]
        .into_iter()
        .filter(|key| raw.contains_key(*key))
        .collect();
    if !keys.is_empty() {
        crate::log::warn(&format!(
            "config.json provider settings are ignored: providers come from the gateway \
             (models.json); keys: {}",
            keys.join(", ")
        ));
    }
    let kinds = raw
        .get("features")
        .and_then(|features| features.get("agentTeam"))
        .and_then(|team| team.get("kinds"))
        .is_some();
    if raw.contains_key("roles") || kinds {
        crate::log::warn(
            "config.json roles and features.agentTeam.kinds are ignored: define roles as \
             markdown files in roles/<name>.md",
        );
    }
}
